+using MessagePack.SourceGenerator;
+using MessagePack.SourceGenerator.Analyzers;
+using Microsoft.CodeAnalysis;
+using Microsoft.CodeAnalysis.CSharp;
+using Microsoft.CodeAnalysis.Diagnostics;
+
+/// <summary>
+/// Tests that exercise data types that are declared in a referenced <em>assembly</em> (i.e. metadata symbols with no syntax),
+/// as opposed to a referenced project whose symbols still carry their declaring syntax.
+/// </summary>
+/// <remarks>
+/// Regression tests for <see href="https://github.com/MessagePack-CSharp/MessagePack-CSharp/issues/2283">issue 2283</see>.
+/// </remarks>
+public class ReferencedAssemblyTypeTests
+{
+    private const string AppSource = """
+        using MessagePack;
+        using Lib;
+
+        namespace App
+        {
+            [MessagePackObject]
+            public sealed partial class Cmd
+            {
+                [Key(0)]
+                public string Scope { get; set; }
+
+                [Key(1)]
+                public Item<int> Member { get; set; }
+            }
+        }
+        """;
+
+    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);
+
+    private static readonly CSharpCompilationOptions CompilationOptions = new(OutputKind.DynamicallyLinkedLibrary);
+
+    /// <summary>
+    /// Verifies that neither the generator nor the analyzer throws when a member's type is a closed generic value type
+    /// that is declared in a referenced assembly, and that the resolver is still generated.
+    /// </summary>
+    /// <param name="itemDeclaration">The declaration of the <c>Lib.Item&lt;T&gt;</c> type in the referenced assembly.</param>
+    [Theory]
+    [InlineData("public partial record struct Item<T>([property: Key(0)] string Key);")]
+    [InlineData("public partial struct Item<T> { [Key(0)] public string Key { get; set; } }")]
+    [InlineData("public partial struct Item<T> { [Key(0)] public string Key; private int notSerialized; public int Touch() => this.notSerialized++; }")]
+    [InlineData("public partial class Item<T> { [Key(0)] public string Key { get; set; } }")]
+    [InlineData("public partial record class Item<T>([property: Key(0)] string Key);")]
+    public async Task ClosedGeneric_DefinedInReferencedAssembly(string itemDeclaration)
+    {
+        string libSource = $$"""
+            using MessagePack;
+
+            namespace Lib
+            {
+                [MessagePackObject]
+                {{itemDeclaration}}
+            }
+            """;
+
+        ImmutableArray<MetadataReference> references = await GetReferencesAsync();
+        MetadataReference libReference = EmitToMetadataReference("Lib", libSource, references);
+
+        CSharpCompilation app = CSharpCompilation.Create(
+            "App",
+            new[] { CSharpSyntaxTree.ParseText(AppSource, ParseOptions) },
+            references.Add(libReference),
+            CompilationOptions);
+
+        // The generator must not throw, and must still produce the resolver.
+        GeneratorDriver driver = CSharpGeneratorDriver.Create(
+            new[] { new MessagePackGenerator().AsSourceGenerator() },
+            parseOptions: ParseOptions);
+        driver = driver.RunGeneratorsAndUpdateCompilation(app, out _, out _);
+        GeneratorDriverRunResult runResult = driver.GetRunResult();
+        Assert.All(runResult.Results, result => Assert.Null(result.Exception));
+        Assert.Contains(runResult.GeneratedTrees, tree => tree.ToString().Contains("GeneratedMessagePackResolver"));
+
+        // The analyzer must not throw either. An analyzer exception is surfaced as an AD0001 diagnostic.
+        CompilationWithAnalyzers appWithAnalyzers = app.WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()));
+        ImmutableArray<Diagnostic> analyzerDiagnostics = await appWithAnalyzers.GetAnalyzerDiagnosticsAsync();
+        Assert.DoesNotContain(analyzerDiagnostics, d => d.Id == "AD0001");
+    }
+
+    private static async Task<ImmutableArray<MetadataReference>> GetReferencesAsync()
+    {
+        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
+        return frameworkReferences.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
+    }
+
+    /// <summary>
+    /// Compiles source code and returns a reference to the resulting assembly image,
+    /// so that its symbols are seen as metadata symbols by the referencing compilation.
+    /// </summary>
+    private static MetadataReference EmitToMetadataReference(string assemblyName, string source, ImmutableArray<MetadataReference> references)
+    {
+        CSharpCompilation compilation = CSharpCompilation.Create(
+            assemblyName,
+            new[] { CSharpSyntaxTree.ParseText(source, ParseOptions) },
+            references,
+            CompilationOptions);
+
+        using MemoryStream stream = new();
+        Microsoft.CodeAnalysis.Emit.EmitResult emitResult = compilation.Emit(stream);
+        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
+
+        return MetadataReference.CreateFromImage(stream.ToArray());
+    }
+}
